draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a fruit
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.stroke();

  // draw a stick figure eating the fruit
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20); // body
  ctx.lineTo(W/2 + 100, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50); // arm
  ctx.lineTo(W/2 + 150, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 100); // leg
  ctx.lineTo(W/2 + 120, H/2 + 150);
  ctx.stroke();

  // animate the stick figure eating the fruit
  ctx.beginPath();
  ctx.moveTo(W/2 + 150, H/2 + 70); // hand
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2 - 20);
  ctx.stroke();

  ctx.restore();
}
